function selectEvents({body,arrayField,filterField,filterValues,timestampField,lastTs}) {
  if(!body||typeof body!=='object'||Array.isArray(body))throw new Error('The feed must return a JSON object.');
  if([arrayField,filterField,timestampField].some(value=>typeof value!=='string'||!value))throw new Error('Configure the feed field names.');
  if(!Array.isArray(filterValues)||filterValues.some(value=>typeof value!=='string'))throw new Error('filterValues must be an array of strings.');
  if(typeof lastTs!=='string')throw new Error('The saved timestamp must be a string.');
  const raw=body[arrayField]??[];
  if(!Array.isArray(raw))throw new Error('The configured feed array must be an array.');
  const eligible=[];
  for(const entry of raw){
    if(!entry||typeof entry!=='object'||Array.isArray(entry))throw new Error('Feed entries must be objects.');
    if(filterValues.length&&!filterValues.includes(entry[filterField]))continue;
    const value=entry[timestampField];
    if(value!=null&&typeof value!=='string'&&!(typeof value==='number'&&Number.isFinite(value)))throw new Error('Feed timestamps must be comparable strings or finite numbers.');
    const timestamp=value==null?'':String(value);
    if(timestamp>lastTs)eligible.push({entry,timestamp});
  }
  eligible.sort((a,b)=>a.timestamp<b.timestamp?-1:a.timestamp>b.timestamp?1:0);
  const escape=text=>text.replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;');
  const notifications=eligible.map(({entry,timestamp})=>{
    const rawText='🔔 '+(entry[filterField]||'evento')+'\n'+JSON.stringify(entry).slice(0,300);
    const text=escape(rawText);
    if(!text||text.length>4096)throw new Error('A Telegram alert exceeds 4096 characters.');
    return {text,timestamp};
  });
  return {notifications,count:notifications.length,nextTimestamp:eligible.at(-1)?.timestamp??lastTs};
}


